export type DeliveryQuoteChoiceGroupResourceInput = { "allowed_types"?: Array<string>; "availability_status": "ready" | "needs_input" | "needs_checkout_context" | "unavailable"; "candidate_outcomes"?: Record<string, DeliveryCandidateOutcomeResourceInput>; "delivery_choice_group_id": string; "evaluation_status": "complete" | "incomplete" | "degraded"; /** Where the group's items leave from, one leg per origin Location, when all of its methods leave from the same Locations. Omitted when the origin depends on the chosen method, such as shipping from a warehouse or picking up at a store. Each option then lists its own execution_legs. */ "execution_legs"?: Array<DeliveryQuoteExecutionLegResourceInput>; "input_requirements": Array<DeliveryInputRequirementInput>; "line_items": Array<DeliveryQuoteLineItemResourceInput>; /** Types of the delivery methods that can serve this group's items, each listed once, in the order the methods display. A type is listed before its options are priced, such as a local delivery that waits for the buyer's address, and stays listed while its methods need more input or cannot serve the current input. options lists what the buyer can choose now. A method whose type these items do not allow is left out, and the list is empty when no method can serve them. */ "method_types": Array<"shipment" | "pickup" | "local_delivery">; "options": Array<DeliveryOptionProjectionInput>; "previously_selected_delivery_method_id"?: string; "stable_key": string; };
